import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();
const { fontFamily: robotoMonoFamily } = loadRobotoMono();



export type AppleNoteAnimationProps = Record<string, any>;

const AppleNoteAnimation: React.FC<AppleNoteAnimationProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 15,
  fontFamily = "Inter",
  lines = [
    { text: "Total Time", isHeader: true },
    { text: "45 minutes", isHeader: false },
    { text: "PRODUCE", isHeader: true },
    { text: "1 medium shallot", isHeader: false },
    { text: "PANTRY", isHeader: true },
    { text: "1 tablespoon fennel seeds", isHeader: false },
    { text: "9 cloves garlic", isHeader: false },
  ],
  textColor = "#ffffff",
  headerColor = "#d1d1d1",
  cursorColor = "#F2A610",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const activeFont = fontFamily === "Space Grotesk" ? spaceGroteskFamily 
                   : fontFamily === "Roboto Mono" ? robotoMonoFamily 
                   : interFamily;

  const headerFontSize = width * 0.055;
  const textFontSize = width * 0.07;
  const gap = height * 0.02;
  const baseY = height * 0.65; // Position where active typing occurs

  const { processedLines, pauseFramesPerLine } = useMemo(() => {
    let totalChars = lines.reduce((acc, l) => acc + l.text.length, 0);
    let pauseFrames = fps * 0.5; // 0.5s pause after each line
    let totalPauseFrames = lines.length * pauseFrames;
    let availableTypingFrames = (durationInSeconds * fps * 0.85) - totalPauseFrames;
    let framesPerChar = Math.max(0.5, availableTypingFrames / (totalChars || 1));
    
    let currentFrame = fps * 0.5; // Start typing after 0.5s
    let currentY = 0;
    
    const mapped = lines.map((line, i) => {
      const startFrame = currentFrame;
      const endFrame = startFrame + (line.text.length * framesPerChar);
      currentFrame = endFrame + pauseFrames;
      
      // Add extra padding before headers if they aren't the first line
      if (line.isHeader && i > 0) {
        currentY += height * 0.04; 
      }
      
      const y = currentY;
      
      // Estimate line wrapping to accurately calculate height displacement
      const lineSize = line.isHeader ? headerFontSize : textFontSize;
      const charWidth = lineSize * 0.55; // Average char width heuristic
      const containerWidth = width * 0.8;
      const estimatedLines = Math.ceil(Math.max(1, line.text.length) / (containerWidth / charWidth));
      
      // Advance Y coordinate for the next line
      currentY += (lineSize * 1.2 * estimatedLines) + gap;
      
      return { ...line, startFrame, endFrame, y };
    });

    return { processedLines: mapped, pauseFramesPerLine: pauseFrames };
  }, [lines, fps, durationInSeconds, width, height, headerFontSize, textFontSize, gap]);

  // Calculate accumulated Y scroll using physics-based springs
  let scrollY = 0;
  for (let i = 1; i < processedLines.length; i++) {
    // Initiate scroll shortly after previous line completes typing
    const scrollStartFrame = processedLines[i-1].endFrame + (pauseFramesPerLine * 0.2);
    const diff = processedLines[i].y - processedLines[i-1].y;
    
    const progress = spring({
      fps,
      frame: frame - scrollStartFrame,
      config: { damping: 14, stiffness: 120 }
    });
    
    scrollY += diff * progress;
  }

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div style={{
        position: 'absolute',
        left: '10%',
        width: '80%',
        top: 0,
        height: '100%',
      }}>
        {processedLines.map((line, index) => {
          const isVisible = frame >= line.startFrame;
          if (!isVisible) return null;
          
          // Fix: Prevent non-monotonically increasing inputRange for empty lines
          const charsToShow = line.startFrame >= line.endFrame 
            ? line.text.length 
            : Math.floor(interpolate(frame, [line.startFrame, line.endFrame], [0, line.text.length], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }));
            
          const displayedText = line.text.substring(0, charsToShow);
          
          const isActiveLine = frame >= line.startFrame && (!processedLines[index+1] || frame < processedLines[index+1].startFrame);
          
          // Calculate screen position and fade effect
          const screenY = baseY + line.y - scrollY;
          const fadeStart = height * 0.45;
          const fadeEnd = height * 0.15;
          const opacity = interpolate(screenY, [fadeEnd, fadeStart], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp"
          });
          
          // Optimization: Skip rendering fully scrolled-off elements
          if (screenY < 0) return null;

          return (
            <div key={index} style={{
              position: 'absolute',
              top: 0,
              left: 0,
              width: '100%',
              transform: `translateY(${screenY}px)`,
              opacity,
              fontSize: line.isHeader ? headerFontSize : textFontSize,
              fontWeight: line.isHeader ? 700 : 400,
              color: line.isHeader ? headerColor : textColor,
              fontFamily: activeFont,
              letterSpacing: line.isHeader ? '0.05em' : 'normal',
              textTransform: line.isHeader ? 'uppercase' : 'none',
              lineHeight: 1.2,
              whiteSpace: 'pre-wrap',
              textShadow: '0px 2px 8px rgba(0,0,0,0.4)', // Adds depth over video layers
            }}>
              {displayedText}
              {isActiveLine && (
                <span style={{
                  display: 'inline-block',
                  width: width * 0.007,
                  height: '0.9em',
                  backgroundColor: cursorColor,
                  marginLeft: '6px',
                  verticalAlign: 'text-bottom',
                  marginBottom: '0.05em',
                  opacity: Math.floor(frame / 15) % 2 === 0 ? 1 : 0,
                  boxShadow: '0px 0px 4px rgba(0,0,0,0.5)',
                }} />
              )}
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default AppleNoteAnimation;